    { name = "SND_Conjurar", legacy = "MG_Conjurar", icon = "spell:5504", minlevel = 4, body = "#showtooltip\n/cast [mod:alt] {587}; {5504}", fallbacks = {"#showtooltip {5504}\n/cast {5504}"}, note = "Conjura agua; con Alt, comida (la comida llega al 6)." },
    { name = "SND_Varita", legacy = "MG_Varita", icon = "spell:5019", minlevel = 5, body = "#showtooltip\n/cast !{5019}", note = "Dispara la varita sin cortarla." },
