    { name = "SND_Lanza", legacy = "MG_Lanza", icon = "name:Lanza de hielo", minlevel = 22, body = "#showtooltip {n:Lanza de hielo}\n/cast [@mouseover,harm,nodead][] {n:Lanza de hielo}", note = "Lanza de hielo al enemigo bajo el ratón o a tu objetivo." },
    { name = "SND_Contra", legacy = "MG_Contra", icon = "spell:2139", minlevel = 24, body = "#showtooltip {2139}\n/stopcasting\n/cast [@focus,harm,nodead][] {2139}", note = "Corta lo que estés lanzando y usa Contrahechizo en el foco o el objetivo." },
    { name = "SND_Bloque", legacy = "MG_Bloque", icon = "name:Bloqueo de hielo", minlevel = 25, body = "#showtooltip {n:Bloqueo de hielo}\n/stopcasting\n/cancelaura {n:Bloqueo de hielo}\n/cast {n:Bloqueo de hielo}", note = "Bloqueo de hielo; si ya estás dentro, lo cancela. Bloqueo de hielo es un talento (11958 en Classic)." },
