Senda.Knowledge:Register({
  id = "mage-rotation",
  class = "MAGE",
  kind = "rotation",
  title = "Rotación del mago",
  levels = {1, 60},
  order = 100,
  status = "unverified",
  note = "Basada en la guía de Escarcha de Wowhead (Porom, 4-nov).",
  phase = {
    { from = 1, to = 9, spells = {116, 2136, 5019}, text = "1. Descarga de Escarcha antes de que llegue.\n2. Otra mientras se acerca.\n3. Explosión de Fuego para rematar.\n4. Varita si te quedas sin maná." },
    { from = 10, to = 19, spells = {116, 2136, 122, 5019}, text = "1. Descarga de Escarcha x2.\n2. Explosión de Fuego cuando llegue.\n3. Nova de Escarcha y aléjate.\n4. Descarga de Escarcha.\n5. Varita para rematar." },
    { from = 20, to = 39, spells = {116, 122, 2136, 1953}, text = "1. Descarga de Escarcha.\n2. Nova de Escarcha y aléjate.\n3. Lanza de hielo en cuanto esté congelado (o con Dedos de Escarcha).\n4. Descarga de Escarcha.\n5. Explosión de Fuego o Lanza de hielo (comparten 8 s).\n6. Traslación para separarte.", note = "Lanza de hielo es un talento de Forever (22) sin id conocido." },
    { from = 40, to = 60, spells = {116, 120, 133, 2948, 2136}, text = "**Escarcha:** Descarga de Escarcha de relleno. Lanza de hielo con congelación o con Dedos de Escarcha. Cono de frío con 5 cargas de Escalofrío del invierno.\n\n**Fuego (bandas):** Piroexplosión de apertura, Chamuscar hasta 5 cargas, Bola de Fuego de relleno, Explosión de Fuego cuando esté lista, Piroexplosión con 3 de Calentamiento." },
  },
  hud = {
    { when = "Sin objetivo, fuera de combate y mana < 0.5", suggest = "Bebe agua conjurada" },
    { when = "hp < 0.3 y conoces Bloqueo de hielo", suggest = "Bloqueo de hielo", spell = 11958 },
    { when = "hp < 0.35 y llevas Piedra de salud", suggest = "¡Piedra de salud!" },
    { when = "hp < 0.45 y conoces Nova de Escarcha", suggest = "Nova de Escarcha y aléjate", spell = 122 },
    { when = "mana < 0.1 y conoces Evocación", suggest = "Evocación", spell = 12051 },
    { when = "mana < 0.2 y llevas gema de maná", suggest = "Gema de maná" },
    { when = "thp < 0.15 y conoces Explosión de Fuego", suggest = "Explosión de Fuego", spell = 2136 },
    { when = "mana < 0.15 y llevas varita", suggest = "Varita", spell = 5019 },
    { when = "Conoces Descarga de Escarcha", suggest = "Descarga de Escarcha", spell = 116 },
    { when = "Siempre (último recurso)", suggest = "Bola de Fuego", spell = 133 },
  },
  warning = {
    { text = "Sin armadura de escarcha/hielo/mago", when = "No tienes ninguna aura de [ids].armor_buffs (spells.toml)" },
    { text = "Sin Intelecto Arcano", when = "No tienes ninguna aura de [ids].intellect_buffs" },
    { text = "Poca agua", when = "Conoces Conjurar agua y llevas menos de 5 aguas conjuradas" },
    { text = "Sin gema de maná", when = "Conoces Conjurar ágata de maná y no llevas ninguna gema" },
    { text = "Talento(s) sin gastar", when = "Tienes puntos de talento sin gastar" },
    { text = "Bolsas llenas", when = "Menos de 3 huecos libres" },
  },
})

Senda.Knowledge:Register({
  id = "mage-combat",
  class = "MAGE",
  kind = "page",
  title = "Combate en solitario",
  order = 110,
  status = "unverified",
  block = {
    { heading = "El combate básico (Escarcha)", body = "1. Descarga de Escarcha desde lejos. Otra mientras llega: va ralentizado.\n2. Cuando esté cerca: Nova de Escarcha y aléjate durante el tiempo global.\n3. Lanza de hielo en cuanto esté congelado: hace un 300% más. Que el daño rompa la congelación es normal.\n4. Vuelve a Descarga de Escarcha.\n5. Remata con Explosión de Fuego o con la varita." },
    { heading = "Dos enemigos", body = "- Polimorfia en uno (macro SND_Poli con foco) y mata al otro.\n- No le pegues al convertido: se despierta.\n- Bestias y humanoides se pueden convertir; elementales y no-muertos, no." },
    { heading = "Tirar de grupos", body = "- Para que lleguen juntos: Bola de Fuego de rango 1 a 35 m al lejano y Descarga de Escarcha al cercano.\n- Si la Nova falla (resistida), reinicia el combate alejándote.\n- Mordiescarcha congela al azar: en área separa a los enemigos. La build de área no lo lleva." },
    { heading = "Maná", body = "- Agua conjurada siempre. Bebe entre combates.\n- Gema de maná en combate, sin gastar turno. Evocación (8 min) cuando estés seco.\n- Armadura de mago: en Forever el 50% de la regeneración sigue mientras lanzas.\n- El espíritu humano (racial) te da más Espíritu: regeneras más maná fuera de combate.", note = "Armadura de mago: 50% en Forever; algunas guías aún dicen 30%." },
    { heading = "Emergencias, por orden", body = "1. Nova de Escarcha y Traslación.\n2. Voluntad de sobrevivir (racial humana) si te aturden.\n3. Bloqueo de hielo (talento) para cortar el daño.\n4. Mordedura helada para recuperar Nova y Bloqueo de hielo.\n5. Piedra de salud (pídesela a tu compañero brujo: macro SND_Piedra)." },
    { heading = "Raciales humanas en Forever", body = "- **Voluntad de sobrevivir:** quita todos los aturdimientos (3 min).\n- **Percepción:** detectas sigilo durante 20 s (3 min). Útil contra pícaros.\n- **Despiadado:** +1% de crítico con hechizos y ataques (las guías dan cifras entre 1% y 2%).\n- **El espíritu humano:** más Espíritu (5% en la beta; algunas guías dicen que subió al 10%).\n- **Diplomacia** ya no existe.", note = "Cifras de Despiadado (1-2%) y del espíritu humano (5% o 10%) en disputa entre guías." },
  },
})

Senda.Knowledge:Register({
  id = "mage-group",
  class = "MAGE",
  kind = "page",
  title = "Grupo, viajes y PvP",
  order = 120,
  status = "unverified",
  block = {
    { heading = "En mazmorra", body = "- Agua y comida conjuradas para todos antes de empezar.\n- Intelecto Arcano a los que usen maná.\n- Polimorfia al objetivo de la luna (lo asigna el líder).\n- Contrahechizo a los lanzadores peligrosos.\n- Deshacer maldición inferior en el grupo.\n- Espera 2-3 golpes del tanque antes de empezar: tu daño de golpe le quita la amenaza.\n- Área solo si el tanque lo pide y con la Nova a mano." },
    { heading = "Viajes", body = "- Teletransporte a Ventormenta al acabar: vuelves a entrenar al momento.\n- Desde el 40, portales para el grupo." },
    { heading = "PvP", body = "- **Humano:** Voluntad de sobrevivir rompe aturdimientos y Percepción descubre pícaros.\n- **Contra guerreros y pícaros:** Nova, Traslación, Descarga de Escarcha.\n- **Contra sacerdotes y brujos:** Contrahechizo en sus curas o en su Miedo; Polimorfia.\n- **Contra cazadores:** pégate a ellos para entrar en su zona muerta y usa la Nova.\n- **Contra otros magos:** Contrahechizo cuando lancen Polimorfia.\n- Dedos de Escarcha es muy fuerte en PvP." },
  },
})

